-- Student engagement features (push tokens, gamification, spaced repetition,
-- playback/bookmarks, lecture Q&A, offline licences).
--
-- PREFERRED: generate the EF migration instead (it also updates the model snapshot):
--     dotnet ef migrations add AddStudentEngagement
-- Use THIS script only if you apply schema changes by hand. Do NOT do both.
-- (PostgreSQL / Npgsql)

CREATE TABLE IF NOT EXISTS "DeviceTokens" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "UserType" text NOT NULL,
  "UserId" integer NOT NULL,
  "Token" character varying(512) NOT NULL,
  "Platform" character varying(20) NOT NULL,
  "CreatedAt" timestamp with time zone NOT NULL,
  "LastSeenAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_DeviceTokens_Token" ON "DeviceTokens" ("Token");
CREATE INDEX IF NOT EXISTS "IX_DeviceTokens_UserType_UserId" ON "DeviceTokens" ("UserType","UserId");

CREATE TABLE IF NOT EXISTS "PushDispatchLogs" (
  "Key" character varying(200) PRIMARY KEY,
  "SentAt" timestamp with time zone NOT NULL
);

CREATE TABLE IF NOT EXISTS "StudentPointEvents" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "StudentId" integer NOT NULL,
  "Kind" character varying(30) NOT NULL,
  "RefKey" character varying(80) NOT NULL,
  "Points" integer NOT NULL,
  "Percent" integer NULL,
  "OccurredAt" timestamp with time zone NOT NULL,
  "CreatedAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_StudentPointEvents_StudentId_TeacherId_RefKey" ON "StudentPointEvents" ("StudentId","TeacherId","RefKey");
CREATE INDEX IF NOT EXISTS "IX_StudentPointEvents_TeacherId_OccurredAt" ON "StudentPointEvents" ("TeacherId","OccurredAt");

CREATE TABLE IF NOT EXISTS "StudentBadges" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "StudentId" integer NOT NULL,
  "Code" character varying(40) NOT NULL,
  "AwardedAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_StudentBadges_StudentId_TeacherId_Code" ON "StudentBadges" ("StudentId","TeacherId","Code");

CREATE TABLE IF NOT EXISTS "ReviewCards" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "StudentId" integer NOT NULL,
  "SourceType" character varying(30) NOT NULL,
  "SourceId" integer NOT NULL,
  "QuestionId" integer NOT NULL,
  "CourseKind" character varying(20) NOT NULL,
  "CourseId" integer NOT NULL,
  "CourseName" character varying(200) NOT NULL,
  "SourceTitle" character varying(200) NOT NULL,
  "Text" text NOT NULL,
  "ImageUrl" text NULL,
  "QuestionType" character varying(20) NOT NULL,
  "ChoicesCsv" text NOT NULL,
  "CorrectAnswer" text NOT NULL,
  "Box" integer NOT NULL,
  "DueAt" timestamp with time zone NOT NULL,
  "Reps" integer NOT NULL,
  "Lapses" integer NOT NULL,
  "LastReviewedAt" timestamp with time zone NULL,
  "MasteredAt" timestamp with time zone NULL,
  "IsArchived" boolean NOT NULL,
  "CreatedAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_ReviewCards_Student_Tenant_Source" ON "ReviewCards" ("StudentId","TeacherId","SourceType","SourceId","QuestionId");
CREATE INDEX IF NOT EXISTS "IX_ReviewCards_StudentId_DueAt" ON "ReviewCards" ("StudentId","DueAt");

CREATE TABLE IF NOT EXISTS "ReviewLogs" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "StudentId" integer NOT NULL,
  "CardId" integer NOT NULL,
  "Correct" boolean NOT NULL,
  "BoxBefore" integer NOT NULL,
  "BoxAfter" integer NOT NULL,
  "ReviewedAt" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_ReviewLogs_StudentId_ReviewedAt" ON "ReviewLogs" ("StudentId","ReviewedAt");

CREATE TABLE IF NOT EXISTS "LecturePlaybackPositions" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "StudentId" integer NOT NULL,
  "LectureId" integer NOT NULL,
  "PositionSeconds" integer NOT NULL,
  "DurationSeconds" integer NULL,
  "Completed" boolean NOT NULL,
  "CompletedAt" timestamp with time zone NULL,
  "UpdatedAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_LecturePlaybackPositions_StudentId_LectureId" ON "LecturePlaybackPositions" ("StudentId","LectureId");

CREATE TABLE IF NOT EXISTS "LectureBookmarks" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "StudentId" integer NOT NULL,
  "LectureId" integer NOT NULL,
  "Seconds" integer NOT NULL,
  "Note" character varying(200) NULL,
  "CreatedAt" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_LectureBookmarks_StudentId_LectureId" ON "LectureBookmarks" ("StudentId","LectureId");

CREATE TABLE IF NOT EXISTS "LectureComments" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "LectureId" integer NOT NULL,
  "ParentId" integer NULL,
  "AuthorRole" character varying(10) NOT NULL,
  "AuthorId" integer NOT NULL,
  "AuthorName" character varying(120) NOT NULL,
  "Body" character varying(2000) NOT NULL,
  "VideoSeconds" integer NULL,
  "IsAccepted" boolean NOT NULL,
  "IsPinned" boolean NOT NULL,
  "IsDeleted" boolean NOT NULL,
  "CreatedAt" timestamp with time zone NOT NULL,
  "EditedAt" timestamp with time zone NULL
);
CREATE INDEX IF NOT EXISTS "IX_LectureComments_LectureId_ParentId" ON "LectureComments" ("LectureId","ParentId");

CREATE TABLE IF NOT EXISTS "OfflineGrants" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "TeacherId" integer NOT NULL,
  "StudentId" integer NOT NULL,
  "ItemType" character varying(10) NOT NULL,
  "ItemId" integer NOT NULL,
  "GrantedAt" timestamp with time zone NOT NULL,
  "ExpiresAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_OfflineGrants_StudentId_ItemType_ItemId" ON "OfflineGrants" ("StudentId","ItemType","ItemId");
